/* WINTER STRONG — framework-free offline PWA. All data stays in localStorage. */
(() => {
'use strict';
const PROGRAM = window.WINTER_PROGRAM;
const V5 = window.WINTER_V5;
const STORE = 'winter-strong-training-v1';
const DAY_ORDER = ['mon','tue','wed','thu','fri','sat','sun'];
const LABELS = {mon:'Lower A + Core A',tue:'Upper A',wed:'Mobility + Walk',thu:'Lower B + Core B',fri:'Upper B',sat:'Cardio + Core C',sun:'Recovery'};
const MOBILITY_PLANS = {"mon": {"title": "Upper-body & spine reset", "items": [{"name": "Thoracic open book", "dose": "5 each side"}, {"name": "Shoulder CARs", "dose": "5 each direction / side"}, {"name": "Comfortable wall slides", "dose": "8 reps"}, {"name": "Cross-body shoulder stretch", "dose": "20 seconds each side"}, {"name": "Cat-cow", "dose": "8 slow cycles"}, {"name": "Easy seated breathing", "dose": "6 slow breaths"}]}, "tue": {"title": "Hips & ankles", "items": [{"name": "90/90 hip switches", "dose": "60–90 seconds"}, {"name": "Hip CARs", "dose": "3 each direction / side"}, {"name": "Adductor rock-backs", "dose": "6 each side"}, {"name": "Knee-to-wall ankle rocks", "dose": "8 each side"}, {"name": "Ankle CARs", "dose": "5 each direction / side"}, {"name": "Easy seated breathing", "dose": "6 slow breaths"}]}, "wed": {"title": "Full-body mobility", "items": [{"name": "90/90 hip switches", "dose": "60–90 seconds"}, {"name": "Half-kneeling hip flexor stretch", "dose": "30 sec each side"}, {"name": "Thoracic open book", "dose": "5 each side"}, {"name": "Comfortable wall slides", "dose": "8 reps"}, {"name": "Scapular push-up plus", "dose": "8–10 reps"}, {"name": "Easy breathing + gentle neck retraction", "dose": "60 seconds"}, {"name": "Hip CARs", "dose": "3 each direction / side"}, {"name": "Knee-to-wall ankle rocks", "dose": "8 each side"}, {"name": "Cat-cow", "dose": "8 slow cycles"}]}, "thu": {"title": "Shoulders & thoracic spine", "items": [{"name": "Shoulder CARs", "dose": "5 each direction / side"}, {"name": "Thread the needle", "dose": "5 each side"}, {"name": "Comfortable wall slides", "dose": "8 reps"}, {"name": "Cross-body shoulder stretch", "dose": "20 seconds each side"}, {"name": "Quadruped thoracic rotations", "dose": "6 each side"}, {"name": "Easy seated breathing", "dose": "6 slow breaths"}]}, "fri": {"title": "Hips, ankles & gentle spine", "items": [{"name": "Hip CARs", "dose": "3 each direction / side"}, {"name": "Adductor rock-backs", "dose": "6 each side"}, {"name": "Knee-to-wall ankle rocks", "dose": "8 each side"}, {"name": "Ankle CARs", "dose": "5 each direction / side"}, {"name": "Supine knee sways", "dose": "8 each side"}, {"name": "Easy seated breathing", "dose": "6 slow breaths"}]}, "sat": {"title": "Gentle full-body recovery", "items": [{"name": "Cat-cow", "dose": "8 slow cycles"}, {"name": "Thoracic open book", "dose": "5 each side"}, {"name": "90/90 hip switches", "dose": "60–90 seconds"}, {"name": "Gentle calf stretch", "dose": "20 seconds each side"}, {"name": "Supported chest opener", "dose": "20–30 seconds"}, {"name": "Easy seated breathing", "dose": "6 slow breaths"}]}, "sun": {"title": "Rest-day reset", "items": [{"name": "Supine knee sways", "dose": "8 each side"}, {"name": "Cat-cow", "dose": "8 slow cycles"}, {"name": "Supported squat sit", "dose": "20–30 seconds"}, {"name": "Cross-body shoulder stretch", "dose": "20 seconds each side"}, {"name": "Gentle calf stretch", "dose": "20 seconds each side"}, {"name": "Easy seated breathing", "dose": "6 slow breaths"}]}};
const FULL = {mon:'Monday',tue:'Tuesday',wed:'Wednesday',thu:'Thursday',fri:'Friday',sat:'Saturday',sun:'Sunday'};
const LIFT_DAYS=['mon','tue','thu','fri'];
const AM=(str)=>String(str??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr=AM;
const mondayNow=()=>{const d=new Date(),offset=(d.getDay()+6)%7;d.setDate(d.getDate()-offset);return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');};
function defaultState(){return {version:1,startDate:mondayNow(),week:1,day:DAY_ORDER[(new Date().getDay()+6)%7],tab:'today',sessions:{},checkins:{},lastBackup:null,advancedRir:false};}
function load(){try{const raw=localStorage.getItem(STORE);if(!raw)return defaultState();const s=JSON.parse(raw);if(!s||typeof s!=='object'||!s.sessions||!s.checkins||s.version!==1)throw Error('Invalid');return {...defaultState(),...s,week:Math.max(1,Math.min(20,Number(s.week)||1))};}catch(e){return defaultState();}}
let state=load();let toastId=null;let librarySearch='';let librarySelected=null;let exerciseReturn=null;let infoOpen=false;let travelPreview=null;let restEnd=0;let restDuration=120;let restFinished=false;
const REST_PREF_KEY='winter-strong-rest-prefs-v1';
let restAlert='silent';
try{const prefs=JSON.parse(localStorage.getItem(REST_PREF_KEY)||'{}');if(Number.isInteger(prefs.duration)&&prefs.duration>=10&&prefs.duration<=900)restDuration=prefs.duration;if(prefs.alert==='beep')restAlert='beep';}catch(_e){}
function saveRestPrefs(){try{localStorage.setItem(REST_PREF_KEY,JSON.stringify({duration:restDuration,alert:restAlert}));}catch(_e){}}
let restAudioContext=null;
function prepareRestAudio(){if(restAlert!=='beep')return;try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;if(!restAudioContext)restAudioContext=new AC();if(restAudioContext.state==='suspended')restAudioContext.resume().catch(()=>{});}catch(_e){}}
function beepRestComplete(){if(restAlert!=='beep'||!restAudioContext||restAudioContext.state!=='running')return;try{const ctx=restAudioContext,now=ctx.currentTime,osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.setValueAtTime(660,now);gain.gain.setValueAtTime(0.0001,now);gain.gain.exponentialRampToValueAtTime(0.13,now+0.015);gain.gain.exponentialRampToValueAtTime(0.0001,now+0.23);osc.connect(gain);gain.connect(ctx.destination);osc.start(now);osc.stop(now+0.24);}catch(_e){}}
function stopAndResetRest(){restEnd=0;restFinished=false;restCollapsed=true;updateRestWidget();}

const screen=document.querySelector('#screen');
const weekData=()=>PROGRAM.weeks[String(state.week)];
const phaseIndex=w=>Math.floor((w-1)/4);
const phase=w=>PROGRAM.phases[phaseIndex(w)];
const key=(w,d)=>`w${w}:${d}`;
function getSession(w,d,create=true){const k=key(w,d);if(!state.sessions[k]&&create)state.sessions[k]={entries:{},notes:'',symptoms:'',completed:false,duration:'',minutes:'',mode:'Walk',rpe:'',mobility:{}};return state.sessions[k]||null;}
function getEntry(w,d,i,name,create=true){const s=getSession(w,d,create);if(!s)return null;if(!s.entries[i]&&create)s.entries[i]={name,sets:[],variant:'',notes:'',rir:'',goal:''};return s.entries[i]||null;}
function write(){try{localStorage.setItem(STORE,JSON.stringify(state));}catch(err){toast('Storage is full/unavailable — export a backup');}}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastId);toastId=setTimeout(()=>el.classList.remove('visible'),2500);}
function updateNav(){document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.tab===state.tab));}
function render(){updateNav();screen.innerHTML=state.tab==='today'?today():state.tab==='plan'?plan():state.tab==='progress'?progress():state.tab==='visuals'?visuals():settings();updateRestWidget();}
function weekHeader(){const w=weekData(),ph=phase(state.week);return `<section class="hero"><div class="hero-head"><div><div class="eyebrow">PHASE ${String(phaseIndex(state.week)+1).padStart(2,'0')} · ${AM(ph.title)}</div><h1>Week ${String(state.week).padStart(2,'0')} <span style="color:#9fe0d6">/ 20</span></h1><p class="hero-sub">${AM(ph.focus)}</p></div><div class="week-controls"><button aria-label="Previous week" data-action="week" data-step="-1" ${state.week===1?'disabled':''}>‹</button><span class="week-count">${String(state.week).padStart(2,'0')}</span><button aria-label="Next week" data-action="week" data-step="1" ${state.week===20?'disabled':''}>›</button></div></div><div class="hero-foot"><span class="pill">${AM(w.theme)}</span><span class="pill">${state.advancedRir?`Target ${AM(w.rir)}`:'Train with control'}</span></div><div class="phase-track"><div style="width:${state.week*5}%"></div></div></section><div class="week-directive"><strong>YOUR WEEKLY ASSIGNMENT</strong>${AM(w.directive)}</div>`;}
function dayPicker(){return `<div class="section"><div class="section-head"><h2>Choose your day</h2><span class="muted small">Saved automatically</span></div><div class="day-scroll">${DAY_ORDER.map(d=>{const s=getSession(state.week,d,false);return `<button class="day-button ${state.day===d?'active':''} ${s?.completed?'done':''}" data-action="day" data-day="${d}"><b>${FULL[d].slice(0,3)}</b><span>${d==='wed'?'Move':d==='sat'?'Core':d==='sun'?'Rest':LIFT_DAYS.includes(d)?'Lift':''}</span><i class="dot"></i></button>`;}).join('')}</div></div>`;}
function activeExercises(w,d){const ss=getSession(w,d,false);return ss?.travel?.active?ss.travel.exercises:(PROGRAM.weeks[String(w)].days[d]||[]);}
function loggedSets(entries,exercises){return exercises.reduce((acc,ex,i)=>acc+(entries?.[i]?.sets||[]).slice(0,ex.sets).filter(V5.hasLogged).length,0);}
// The floating timer is a single persistent widget outside #screen.
let restCollapsed=true;
function restViewCard(){return '';} // Replaced by the floating widget (kept for older workout templates).
function restVisible(){return state.tab==='today' && !['wed','sun'].includes(state.day);}
function restWidget(){
 const remaining=restEnd?Math.max(0,Math.ceil((restEnd-Date.now())/1000)):restDuration;
 const label=restFinished?'Done':formatTime(remaining);
 const status=restFinished?' is-complete':restEnd?' is-running':'';
 const presetList=[30,60,120,180];
 return `<div class="floating-rest-shell ${restCollapsed?'is-collapsed':''}${status}" aria-label="Workout rest timer">
   <div class="floating-rest-head">
     <span class="floating-rest-title">◷ Rest</span>
     <strong id="rest-time" role="timer" aria-label="Rest time remaining">${label}</strong>
     ${restEnd||restFinished?`<button type="button" class="floating-rest-stop" data-action="timer-stop" aria-label="Stop and reset rest timer" title="Stop and reset">×</button>`:''}
     <button type="button" class="floating-rest-toggle" data-action="timer-toggle" aria-label="${restCollapsed?'Expand':'Collapse'} rest timer" aria-expanded="${!restCollapsed}">${restCollapsed?'⌃':'⌄'}</button>
   </div>
   <div class="floating-rest-controls" ${restCollapsed?'hidden':''}>
     <div class="floating-rest-presets">${presetList.map(t=>`<button type="button" class="btn smallbtn ${restDuration===t?'timer-active':''}" data-action="timer-preset" data-secs="${t}" aria-pressed="${restDuration===t}">${t===30?'30s':t/60+'m'}</button>`).join('')}
       <label class="floating-rest-custom-label">Custom <input class="floating-rest-custom" type="number" min="10" max="900" step="5" inputmode="numeric" data-action="timer-custom" aria-label="Custom rest seconds" placeholder="sec" value="${presetList.includes(restDuration)?'':restDuration}"></label>
     </div>
     <div class="floating-rest-actions">
       <button type="button" class="btn smallbtn primary" data-action="timer-start">${restEnd?'Restart':'Start'}</button>
       <button type="button" class="btn smallbtn" data-action="timer-stop">× Stop & Reset</button>
       <label class="floating-rest-alert-label">Alert <select data-action="timer-alert" aria-label="Rest timer completion alert"><option value="silent" ${restAlert==='silent'?'selected':''}>Silent</option><option value="beep" ${restAlert==='beep'?'selected':''}>Beep</option></select></label>
     </div>
   </div>
 </div>`;
}
function updateRestWidget(){
 let host=document.querySelector('#floating-rest');
 if(!host){host=document.createElement('aside');host.id='floating-rest';document.querySelector('#app').appendChild(host);}
 const visible=restVisible();host.hidden=!visible;
 if(visible){host.innerHTML=restWidget();document.body.classList.add('has-floating-rest');}
 else document.body.classList.remove('has-floating-rest');
}

function formatTime(sec){const t=Math.max(0,Number(sec)||0);return `${Math.floor(t/60).toString().padStart(2,'0')}:${Math.floor(t%60).toString().padStart(2,'0')}`;}
function travelControls(w,d,s){if(!['mon','tue','thu','fri','sat'].includes(d))return '';
 const t=s.travel;
 return `<div class="panel travel-section" style="margin-bottom:12px"><div class="section-head"><h3>Travel / shorter workout</h3><span class="badge">${t?.active?'Modified session':'Optional'}</span></div>${t?.active?`<p class="small">${t.profile==='hotelroom'?'Hotel room':t.profile==='hotelgym'?'Hotel gym':'Full gym'} · ${t.minutes} minutes. Original strength targets are preserved separately.</p><div class="actions" style="margin-top:10px"><button class="btn smallbtn" data-action="travel-edit">Change replacement</button><button class="btn smallbtn" data-action="travel-original">Return to original</button></div>`:`<p class="muted small" style="margin-bottom:11px">Keep today's training focus when you're away from your usual equipment. Travel sets do not advance your home-gym weights.</p><button class="btn light" data-action="travel-edit">Preview a modified workout →</button>`}
 ${t?.active&&s.travelHistory?.length?`<p class="helper">${s.travelHistory.length} prior travel workout(s) archived in your backup and CSV export.</p>`:''}${travelPreview?travelPreviewMarkup(w,d):''}</div>`;}
function travelPreviewMarkup(w,d){const ss=getSession(w,d),profile=travelPreview.profile,minutes=travelPreview.minutes,plan=V5.travelPlan(profile,d,minutes,weekData().days[d]||[]);
 const labels={hotelroom:'Hotel room · bodyweight',hotelgym:'Hotel gym · dumbbells',fullgym:'Full gym · original exercise choices'};
 return `<div class="travel-preview"><label class="field-label">Available equipment</label><select class="select-field" data-input="travel-choice" data-part="profile"><option value="hotelroom" ${profile==='hotelroom'?'selected':''}>Hotel room — no equipment</option><option value="hotelgym" ${profile==='hotelgym'?'selected':''}>Hotel gym — dumbbells / bench</option><option value="fullgym" ${profile==='fullgym'?'selected':''}>Full gym — normal program</option></select><label class="field-label" style="margin-top:9px">Time available</label><select class="select-field" data-input="travel-choice" data-part="minutes">${[15,30,45].map(n=>`<option value="${n}" ${minutes===n?'selected':''}>${n} minutes</option>`).join('')}</select><div class="preview-plan"><b>${labels[profile]} · ${minutes} min</b><ol>${plan.map(e=>`<li>${AM(e.name)} · ${e.sets} × ${e.low}–${e.high}${e.unit==='sec'?' sec':''}</li>`).join('')}</ol></div><p class="helper">Suggested duration is approximate. Hotel-room routines have limited pulling resistance; they're a temporary replacement, not equivalent to heavy strength training.</p><div class="actions"><button class="btn primary" data-action="travel-accept">Use this workout</button><button class="btn" data-action="travel-cancel">Cancel</button></div></div>`;}
function readinessControl(w,d,s){return `<div class="readiness"><label class="field-label" for="readiness-select">How do you feel today? <span class="muted">(optional)</span></label><select id="readiness-select" class="select-field" data-input="session" data-day="${d}" data-part="readiness"><option value="" ${!s.readiness?'selected':''}>No check-in</option><option value="great" ${s.readiness==='great'?'selected':''}>Great</option><option value="normal" ${s.readiness==='normal'?'selected':''}>Normal</option><option value="fatigued" ${s.readiness==='fatigued'?'selected':''}>Fatigued — keep it easier</option><option value="pain" ${s.readiness==='pain'?'selected':''}>Pain / flare-up — modify or stop</option></select>${s.readiness==='pain'?'<p class="warn" style="margin-top:8px">Avoid painful movements. A training goal is never a requirement to push through pain.</p>':''}</div>`;}
function today(){const d=state.day,w=state.week,s=getSession(w,d),data=weekData(),travel=!!s.travel?.active,exercises=activeExercises(w,d);let count=0,total=0;
 exercises.forEach((ex,i)=>{total+=ex.sets;const e=travel?s.travel.entries?.[i]:getEntry(w,d,i,ex.name,false);count+=(e?.sets||[]).slice(0,ex.sets).filter(V5.hasLogged).length;});
 return `${weekHeader()}${dayPicker()}<section class="section"><div class="section-head"><div><div class="eyebrow muted">${FULL[d].toUpperCase()}</div><h2>${LABELS[d]}</h2></div>${data.days[d]?`<span class="counter">${count}/${total} sets</span>`:''}</div>${d==='wed'?`${movementView(w,d,s)}${mobilityPanel(w,d,s)}`:d==='sun'?`${restView()}${mobilityPanel(w,d,s)}`:`${travelControls(w,d,s)}${readinessControl(w,d,s)}${restViewCard()}${d==='sat'?movementView(w,d,s,true):''}${exercises.map((ex,i)=>travel?travelExerciseView(w,d,ex,i):exerciseView(w,d,ex,i)).join('')}${sessionFinish(w,d,s)}${mobilityPanel(w,d,s)}`}</section>`;}

function findPrior(w,d,name,variation){const currentIndex=(w-1)*7+DAY_ORDER.indexOf(d);for(let wi=w;wi>=1;wi--){for(const di of ['fri','thu','tue','mon','sat']){const index=(wi-1)*7+DAY_ORDER.indexOf(di);if(index>=currentIndex)continue;const ss=getSession(wi,di,false);if(!ss||ss.travel?.active)continue;for(const [id,e] of Object.entries(ss.entries||{})){if(e.name!==name||(e.variant||'').trim()!==variation.trim())continue;const ex=PROGRAM.weeks[String(wi)].days[di]?.[Number(id)];if(!ex)continue;const sets=(e.sets||[]).slice(0,ex.sets).filter(q=>q?.reps!==''&&q?.reps!==undefined);if(sets.length)return {wi,di,e,ex,sets};}}}return null;}
function loadFor(ex,s){const v=(s.weight||'').trim();return v?`${v}${/^BW/i.test(v)?'':' lb'}`:'BW';}
function nextJump(name){if(/barbell back squat|front.*squat|romanian deadlift|hip thrust/i.test(name))return '+5–10 lb total';if(/barbell|EZ/i.test(name))return '+2.5–5 lb total';if(/DB|dumbbell|lateral|curl|press|raise/i.test(name))return '+smallest DB jump';if(/pull-up|chin-up|push-up/i.test(name))return '+smallest vest/plate increment';return '+smallest sensible increment';}
function v5Prior(w,d,ex,variation){return findPrior(w,d,ex.name,variation);}
function v5Rx(w,d,ex,i,en){const prior=v5Prior(w,d,ex,en.variant||'');return {prior,rx:V5.prescribe(ex,w,prior,getSession(w,d).readiness||'',weekData())};}
function infoButton(){return `<button class="info-button" data-action="rir-info" aria-label="What is RIR, reps in reserve?" title="Explain reps in reserve" type="button">ⓘ</button>`;}
function logRows(w,d,ex,i,en,travel=false){const advanced=!!state.advancedRir;
 return `<div class="log-header ${advanced?'':'simple-logging'}"><span>Set</span><span>Weight</span><span>${ex.unit==='sec'?'Seconds':'Reps'}</span>${advanced?`<span class="with-info">RIR ${infoButton()}</span>`:''}</div>${Array.from({length:ex.sets},(_,j)=>{const ss=en.sets?.[j]||{},a=travel?'travel-set':'set';return `<div class="log-row ${advanced?'':'simple-logging'}"><span class="set-num">${j+1}</span><input aria-label="${attr(ex.name)} set ${j+1} weight" class="numeric" data-input="${a}" data-day="${d}" data-ex="${i}" data-set="${j}" data-part="weight" type="text" inputmode="decimal" autocomplete="off" placeholder="BW / 50" value="${attr(ss.weight??'')}"><input aria-label="${attr(ex.name)} set ${j+1} ${ex.unit}" class="numeric" data-input="${a}" data-day="${d}" data-ex="${i}" data-set="${j}" data-part="reps" type="number" inputmode="numeric" min="0" max="999" step="1" placeholder="${ex.low}" value="${attr(ss.reps??'')}">${advanced?`<select class="select-field rir-select" aria-label="${attr(ex.name)} set ${j+1} reps in reserve" data-input="${a}" data-day="${d}" data-ex="${i}" data-set="${j}" data-part="rir"><option value="">—</option>${[0,1,2,3,4,5].map(n=>`<option value="${n}" ${String(ss.rir??'')===String(n)?'selected':''}>${n===5?'5+':n}</option>`).join('')}</select>`:''}</div>`;}).join('')}`;
}
function exerciseView(w,d,ex,i){const en=getEntry(w,d,i,ex.name),{prior,rx}=v5Rx(w,d,ex,i,en),logged=(en.sets||[]).filter(V5.hasLogged).length;
 const priorLine=prior?`Last time (W${prior.wi}): ${prior.sets.map(s=>`${AM(s.weight||'BW')} × ${AM(s.reps)}${state.advancedRir&&s.rir!==undefined&&s.rir!==''?' · RIR '+AM(s.rir):''}`).join(' | ')}`:'No previous session for this exact exercise / variation.';
 return `<article class="exercise-card"><div class="exercise-header"><span class="exercise-num">${i+1}</span><h3><button class="exercise-link" data-action="show-exercise" data-name="${attr(ex.name)}" aria-label="View how to do ${attr(ex.name)}">${AM(ex.name)} <span aria-hidden="true">ⓘ</span></button></h3><span class="badge">${ex.sets} × ${ex.low}–${ex.high}${ex.unit==='sec'?'s':''}</span></div><div class="exercise-prescription">${logged}/${ex.sets} sets logged${state.advancedRir?` · Suggested RIR ${rx.targetRir} ${infoButton()}`:''}</div><div class="goal-box"><div class="goal-label">🎯 TODAY'S RECOMMENDED GOAL</div><strong>${AM(rx.display)}</strong><p>${AM(rx.reason)}</p><span class="goal-prior">${priorLine}</span></div>${prior?`<div class="actions" style="margin:0 0 10px"><button class="btn smallbtn light" data-action="copy-last" data-day="${d}" data-ex="${i}">↻ Use previous weights</button><button class="btn smallbtn" data-action="fill-goal" data-day="${d}" data-ex="${i}">↓ Fill goal weights</button></div>`:`<p class="helper">Start with a manageable baseline; prescribed reps are a target, not a mandate.</p>`}${logRows(w,d,ex,i,en)}<div class="extra-fields"><label class="flexgrow">Exercise substitution / variation<input aria-label="Substitute exercise for ${attr(ex.name)}" class="text-field" data-input="exercise" data-part="variant" data-day="${d}" data-ex="${i}" placeholder="Optional alternative (tracked separately)" value="${attr(en.variant)}"></label></div>${en.goal?`<p class="helper">Earlier manual goal (preserved): ${AM(en.goal)}</p>`:''}</article>`;}
function travelExerciseView(w,d,ex,i){const t=getSession(w,d).travel,en=t.entries[i]||(t.entries[i]={name:ex.name,sets:[]});const item=(window.WINTER_EXERCISE_LIBRARY||[]).find(x=>x.name===ex.name);const cues=V5.travelNew[ex.name];return `<article class="exercise-card"><div class="exercise-header"><span class="exercise-num">${i+1}</span><h3>${item?`<button class="exercise-link" data-action="show-exercise" data-name="${attr(ex.name)}">${AM(ex.name)} ⓘ</button>`:AM(ex.name)}</h3><span class="badge">${ex.sets} × ${ex.low}–${ex.high}${ex.unit==='sec'?'s':''}</span></div><div class="exercise-prescription">Travel alternative · Use controlled form and a manageable effort${state.advancedRir?` · Suggested RIR ${V5.rirTarget(weekData())} ${infoButton()}`:''}</div>${cues?`<details class="travel-cues"><summary>How to do this exercise (text guide)</summary><ol>${cues.slice(0,3).map(x=>`<li>${AM(x)}</li>`).join('')}</ol><p>${AM(cues[3])}</p><a href="https://www.youtube.com/results?search_query=${encodeURIComponent(ex.name+' exercise proper form')}" target="_blank" rel="noopener noreferrer">Find a video demonstration ↗</a></details>`:''}${logRows(w,d,ex,i,en,true)}</article>`;}

function effortGuidance(w,d,mode){
 const recovery=[4,8,12,16,20].includes(Number(w));
 if(recovery)return {range:'3–4 / 10',label:'Easy / recovery',description:'Keep the pace comfortable. You should be able to hold a conversation without difficulty.'};
 if(mode==='Kenpo X'||mode==='Brisk intervals')return {range:'6–7 / 10',label:'Moderate to challenging',description:'Breathing is noticeably heavier. You can speak in short phrases; ease off if form or comfort suffers.'};
 if(d==='wed')return {range:'3–5 / 10',label:'Easy to moderate',description:'Comfortable to brisk movement. You should still be able to speak in full sentences.'};
 return {range:'5–6 / 10',label:'Moderate',description:'You are breathing harder but can still speak in sentences. No need to push to maximum effort.'};
}
function effortLabel(n){if(n<=2)return 'Very easy';if(n<=4)return 'Easy';if(n<=6)return 'Moderate';if(n<=8)return 'Hard';return 'Very hard';}
function effortInfoButton(){return `<button type="button" class="info-button" data-action="effort-info" aria-label="Explain the effort level scale" title="What is Effort Level?">ⓘ</button>`;}
function mobilityItems(d){return MOBILITY_PLANS[d].items;}
function mobilityComplete(w,d){const s=getSession(w,d,false);return !!s&&mobilityItems(d).every((m,i)=>!!s.mobility?.[i]);}
function mobilityCount(w){return DAY_ORDER.filter(d=>mobilityComplete(w,d)).length;}
function mobilityPanel(w,d,s){const plan=MOBILITY_PLANS[d],items=plan.items,done=items.filter((m,i)=>s.mobility?.[i]).length,wed=d==='wed';
 return `<div class="panel daily-mobility" style="margin-top:14px"><div class="section-head"><div><div class="caps muted">${wed?'WEDNESDAY · MAIN FOCUS':'OPTIONAL · AFTER YOUR WORKOUT'}</div><h3>${wed?'Full-body mobility':'Daily mobility'}</h3></div><span class="badge">${wed?'Dedicated move day':'Optional'}</span></div><p class="small muted">${AM(plan.title)} · ${wed?'Extended gentle recovery routine':'Around 10 minutes, at your own pace'}. Move comfortably, without adding fatigue or forcing range.</p><div class="mobility-status"><strong>${done} of ${items.length} movements</strong><span>${done===items.length?'✓ Session complete':'Check off what you complete'}</span></div><div class="mobility-progress"><div style="width:${100*done/items.length}%"></div></div><div class="toggle-mobility">${items.map((m,i)=>`<div class="mobility-row"><label class="checkitem mobility-check"><input type="checkbox" data-input="mobility" data-day="${d}" data-index="${i}" ${s.mobility?.[i]?'checked':''}><span>${AM(m.name)} <span class="muted small">· ${AM(m.dose)}</span></span></label><button type="button" class="mobility-info" data-action="show-exercise" data-name="${attr(m.name)}" data-mobility-index="${i}" aria-label="Instructions for ${attr(m.name)}" title="Movement instructions">ⓘ</button></div>`).join('')}</div><p class="helper">${wed?'Wednesday mobility is your main recovery assignment.':'Skipping this optional routine never reduces workout completion.'} Your checkmarks save automatically and you can return later.</p></div>`;
}
function movementView(w,d,s,compact=false){const data=weekData();const assignment=compact?data.cardio.sat:data.cardio.wed;const isDeload=w%4===0;
 return `<div class="panel" style="margin-bottom:12px"><div class="section-head"><div><div class="caps muted">${compact?'SATURDAY CONDITIONING':'WEDNESDAY AEROBIC BASE'}</div><h3>${compact?'Walk / optional Kenpo X':'Walking + mobility'}</h3></div>${isDeload?'<span class="badge">Recovery</span>':''}</div><p class="small muted">${AM(assignment)}</p><div class="space"></div><div class="setup-row"><div><label class="field-label">Activity type</label><select class="select-field" data-input="session" data-day="${d}" data-part="mode">${['Walk','Brisk intervals','Yoga X','X Stretch','Kenpo X','Other'].map(v=>`<option value="${v}" ${s.mode===v?'selected':''}>${v}</option>`).join('')}</select></div><div><label class="field-label">Minutes completed</label><input class="text-field" type="number" inputmode="numeric" min="0" max="300" data-input="session" data-day="${d}" data-part="minutes" placeholder="30" value="${attr(s.minutes)}"></div></div><div class="space"></div><div class="effort-recommendation"><div class="field-label">Recommended Effort Level ${effortInfoButton()}</div><strong>${effortGuidance(w,d,s.mode).range} · ${effortGuidance(w,d,s.mode).label}</strong><p class="small muted">${effortGuidance(w,d,s.mode).description}</p></div><label class="field-label" for="effort-actual-${d}">Your Effort Level ${effortInfoButton()}</label><select id="effort-actual-${d}" class="select-field" data-input="session" data-day="${d}" data-part="rpe" aria-label="Your actual effort level, 1 to 10"><option value="">Not recorded</option>${Array.from({length:10},(_,i)=>i+1).map(n=>`<option ${String(s.rpe)===String(n)?'selected':''} value="${n}">${n} / 10 — ${effortLabel(n)}</option>`).join('')}</select><p class="helper">After your session, record how hard it actually felt. This does not change the recommended effort.</p></div>`;
}
function sessionFinish(w,d,s){return `<div class="panel" style="margin-top:14px"><h3 class="card-title">Finish your workout</h3>${s.completed?completionSummary(w,d,s):''}<div class="setup-row"><div><label class="field-label">Workout duration (min)</label><input class="text-field" type="number" inputmode="numeric" min="0" data-input="session" data-day="${d}" data-part="duration" placeholder="45" value="${attr(s.duration)}"></div><div><label class="field-label">Neck / shoulder / hip symptoms</label><select class="select-field" data-input="session" data-day="${d}" data-part="symptoms">${['','None','Better','Same','Worse'].map(v=>`<option value="${v}" ${s.symptoms===v?'selected':''}>${v||'Select'}</option>`).join('')}</select></div></div><div class="workout-note"><label class="field-label">Session notes / how to improve next time</label><textarea data-input="session" data-day="${d}" data-part="notes" placeholder="How did the workout go? Note technique, recovery and any discomfort.">${AM(s.notes)}</textarea></div><div class="actions" style="margin-top:12px"><button class="btn ${s.completed?'light':'primary'} full" data-action="complete" data-day="${d}">${s.completed?'✓ Completed — tap to reopen':'✓ Mark session completed'}</button></div><p class="helper">Your sets and notes save as you type. Completing a travel session records it as modified; original lifting goals remain separate.</p></div>`;}
function completionSummary(w,d,s){const travel=!!s.travel?.active,exs=activeExercises(w,d),entries=travel?s.travel.entries:s.entries,sets=loggedSets(entries,exs);
 const met=exs.filter((ex,i)=>{const en=entries?.[i];if(!en)return false;const completed=(en.sets||[]).slice(0,ex.sets).filter(V5.hasLogged);if(completed.length!==ex.sets)return false;return completed.every(q=>Number(q.reps)>=Number(ex.low));}).length;
 const next=PROGRAM.weeks[String(w+1)]?.days?.[d],preview=(!travel&&next)?next.slice(0,2).map(nextEx=>{const currentIndex=exs.findIndex(x=>x.name===nextEx.name);if(currentIndex<0)return '';const en=entries?.[currentIndex];if(!en||(en.sets||[]).filter(V5.hasLogged).length)return '';const prior={wi:w,ex:exs[currentIndex],e:en,sets:(en.sets||[]).filter(V5.hasLogged)};const rx=V5.prescribe(nextEx,w+1,prior,'',PROGRAM.weeks[String(w+1)]);return `<li>${AM(nextEx.name)}: ${AM(rx.display)}</li>`;}).filter(Boolean):[];
 return `<div class="completion-box"><strong>✓ ${travel?'Modified workout':'Workout'} recorded</strong><p>${exs.length} exercises · ${sets} sets logged · ${met}/${exs.length} exercises at or above minimum reps</p>${travel?'<p>Home-gym progression remains tied to your original lift records.</p>':preview.length?`<p><b>Next week's early preview:</b></p><ul>${preview.join('')}</ul>`:'<p>Next targets use your recorded weights and reps, with recovery-week adjustments.</p>'}</div>`;}
function restView(){return `<div class="panel rest-day"><div class="rest-icon">☀</div><h2>Recover with intention.</h2><p class="muted" style="margin-top:8px">Rest, take an easy walk, and review your next week's recommended targets. Recovery is part of the program.</p><button class="btn light" style="margin-top:18px" data-action="tab" data-tab="progress">Open progress tracker →</button></div>`;}
function plan(){let w=weekData();return `<div class="section-head"><div><div class="eyebrow muted">THE ROADMAP</div><h1>20-week program</h1></div><span class="badge">5 phases</span></div><p class="muted small" style="margin-top:7px">One plan, five evolving training blocks. Each week has its own set counts, rep ranges and effort target.</p><div class="section phase-list">${PROGRAM.phases.map((ph,i)=>`<button class="phase-item ${i===phaseIndex(state.week)?'active':''}" data-action="week-set" data-week="${ph.weeks[0]}"><div class="phase-num">${String(i+1).padStart(2,'0')}</div><div><b>${AM(ph.title)}</b><p>Weeks ${ph.weeks.join('–')} · ${AM(ph.focus)}</p></div><span class="muted">›</span></button>`).join('')}</div><section class="section"><div class="section-head"><h2>Select any week</h2><span class="muted small">Current: ${state.week}</span></div><div class="week-grid">${Array.from({length:20},(_,i)=>`<button class="week-chip ${state.week===i+1?'active':''}" data-action="week-set" data-week="${i+1}">W${String(i+1).padStart(2,'0')}</button>`).join('')}</div></section><section class="section"><div class="panel"><div class="eyebrow muted">WEEK ${String(state.week).padStart(2,'0')} ASSIGNMENT</div><h2 style="margin:5px 0 8px">${AM(w.theme)}</h2><span class="badge">${state.advancedRir?AM(w.rir):'Controlled effort'}</span><p style="margin-top:12px;font-size:13px">${AM(w.directive)}</p><hr class="subtle-rule"><h3>Training split</h3>${['mon','tue','wed','thu','fri','sat','sun'].map(d=>`<button class="program-matrix" data-action="choose-workout" data-day="${d}" style="display:block;width:100%;border-color:#edf1f2;text-align:left"><div class="rowhead"><b>${FULL[d]}</b><span class="tag">${w.days[d]?`${w.days[d].length} exercises`:'Mobility / recovery'}</span></div><div class="sub">${AM(LABELS[d])}</div></button>`).join('')}</div></section><div class="notice">Tip: On the Workout tab, choose the day you want. Your actual loads and reps are stored separately from the prescription.</div>`;}
function checkin(w){return state.checkins[String(w)]||{};}
function doneCount(w){return LIFT_DAYS.filter(d=>getSession(w,d,false)?.completed).length;}
function bestSetFor(w,match){const dmap=PROGRAM.weeks[String(w)].days;let best=null;for(const d of [...LIFT_DAYS,'sat']){(dmap[d]||[]).forEach((e,i)=>{if(!match.test(e.name))return;if(getSession(w,d,false)?.travel?.active)return;const en=getEntry(w,d,i,e.name,false);if(!en||String(en.variant||'').trim())return;for(const set of (en.sets||[]).slice(0,e.sets)){if(!set||set.reps===''||!set.reps)continue;const raw=String(set.weight||'BW').trim(),weight=/^BW/i.test(raw)?0:Number(raw)||0;const score=weight>0?weight*(1+Number(set.reps)/30):Number(set.reps);if(!best||score>best.score)best={weight:raw,reps:set.reps,score};}});}return best?`${best.weight}${/^BW/i.test(best.weight)?'':' lb'} × ${best.reps}`:'—';}
function progress(){const w=state.week,c=checkin(w);const filledWeeks=Array.from({length:20},(_,i)=>i+1);const total=filledWeeks.reduce((sum,w)=>sum+doneCount(w),0);const totalLoggedSets=Object.entries(state.sessions).reduce((sum,[k,s])=>{const wi=Number(k.match(/w(\d+)/)?.[1]),d=k.split(':')[1],p=PROGRAM.weeks[String(wi)]?.days?.[d];if(!p)return sum;return sum+loggedSets(s.travel?.active?s.travel.entries:s.entries,s.travel?.active?s.travel.exercises:p);},0);
 return `<div class="section-head"><div><div class="eyebrow muted">YOUR SCOREBOARD</div><h1>Progress</h1></div><span class="badge">Week ${w} / 20</span></div><div class="summary-grid section"><div class="metric"><div class="kicker">Lifting sessions</div><div class="value">${total}<span class="unit"> / 80</span></div></div><div class="metric"><div class="kicker">Working sets logged</div><div class="value">${totalLoggedSets}</div></div></div><div class="panel section"><h3>Weekly consistency</h3><p class="muted small">Completed lift sessions (maximum 4 per week)</p><div class="bars">${filledWeeks.map(wi=>`<div class="bar ${wi===w?'current':''}" title="Week ${wi}: ${doneCount(wi)} of 4 workouts" style="height:${Math.max(4,doneCount(wi)*25)}%"><i>${wi%2===0?wi:''}</i></div>`).join('')}</div><div style="height:20px"></div></div><div class="panel section"><div class="section-head"><h3>Mobility progress</h3><span class="badge">Positive progress</span></div><p class="muted small">Optional on six days; Wednesday is your dedicated mobility day. Only completed routines count, never estimated minutes.</p><div class="mobility-summary"><div><strong>${mobilityCount(w)} / 7</strong><small>Sessions this week</small></div><div><strong>${filledWeeks.reduce((n,wi)=>n+mobilityCount(wi),0)}</strong><small>Sessions across 20 weeks</small></div></div><div class="mobility-week-grid">${DAY_ORDER.map(d=>`<div class="mobility-day"><span>${FULL[d].slice(0,3)}</span><b class="${mobilityComplete(w,d)?'mobility-done':''}">${mobilityComplete(w,d)?'✓':'–'}</b></div>`).join('')}</div><h4 style="margin-top:16px">Weekly mobility sessions</h4><div class="bars mobility-bars">${filledWeeks.map(wi=>`<div class="bar ${wi===w?'current':''}" title="Week ${wi}: ${mobilityCount(wi)} of 7 mobility sessions" style="height:${Math.max(4,mobilityCount(wi)*100/7)}%"><i>${wi%2===0?wi:''}</i></div>`).join('')}</div><p class="helper">No penalties for skipped optional mobility. A completed routine is an additional accomplishment.</p></div><div class="panel section"><div class="section-head"><h3>Week ${w} check-in</h3><button class="btn smallbtn" data-action="tab" data-tab="plan">Change week</button></div><div class="setup-row"><div><label class="field-label">Average weight · lb</label><input type="number" inputmode="decimal" class="text-field" placeholder="200" data-input="checkin" data-part="weight" value="${attr(c.weight)}"></div><div><label class="field-label">Waist at navel · in</label><input type="number" inputmode="decimal" class="text-field" placeholder="32" data-input="checkin" data-part="waist" value="${attr(c.waist)}"></div><div><label class="field-label">Upper-arm measurement · in</label><input type="number" inputmode="decimal" class="text-field" placeholder="Optional" data-input="checkin" data-part="arms" value="${attr(c.arms)}"></div><div><label class="field-label">Sleep average · h</label><input type="number" inputmode="decimal" class="text-field" placeholder="Optional" data-input="checkin" data-part="sleep" value="${attr(c.sleep)}"></div></div><div style="margin-top:12px"><label class="field-label">Weekly notes, photos taken, recovery, shoulder/hip symptoms</label><textarea class="longnote" data-input="checkin" data-part="notes" placeholder="Progress that matters beyond the scale">${AM(c.notes)}</textarea></div><p class="helper">Use similar conditions for weekly weight and waist measurements.</p></div><div class="panel section"><h3>Top work sets by week</h3><p class="muted small" style="margin-top:4px">Highest recorded weight × reps for each movement. Compare like-for-like variations.</p><div class="table-scroll"><table class="data-table"><thead><tr><th>Week</th><th>Bench</th><th>Squat</th><th>Pull-up</th></tr></thead><tbody>${filledWeeks.map(wi=>`<tr><td><b>${wi}</b></td><td>${AM(bestSetFor(wi,/^Barbell bench press$/))}</td><td>${AM(bestSetFor(wi,/^Barbell back squat$/))}</td><td>${AM(bestSetFor(wi,/^Pull-up \/ weighted pull-up$/))}</td></tr>`).join('')}</tbody></table></div></div><div class="panel section"><h3>Body measurements</h3><div class="table-scroll"><table class="data-table"><thead><tr><th>Week</th><th>Weight</th><th>Waist</th><th>Arm</th></tr></thead><tbody>${filledWeeks.filter(wi=>{const c=checkin(wi);return c.weight||c.waist||c.arms||wi===w;}).map(wi=>{const c=checkin(wi);return `<tr><td><b>${wi}</b></td><td>${AM(c.weight||'—')}</td><td>${AM(c.waist||'—')}</td><td>${AM(c.arms||'—')}</td></tr>`;}).join('')}</tbody></table></div></div>`;
}
function visuals(){
 const lib=window.WINTER_EXERCISE_LIBRARY||[];
 const item=lib.find(x=>x.name===librarySelected);
 if(item)return `<div class="library-top"><button class="btn smallbtn" data-action="library-back">← All exercises</button></div><div class="eyebrow muted">EXERCISE REFERENCE</div><h1 style="margin:8px 0">${AM(item.name)}</h1><p class="muted small">${AM(item.group)} · ${AM(item.equipment)}</p><section class="panel section">${item.images?.length?`<h3>Movement photos</h3><div class="exercise-image-grid">${item.images.map((im,i)=>{const labels=['1 · Starting position','2 · Working position','3 · Finish / return']; const alts=['Starting','Working','Finishing']; return `<figure class="exercise-figure"><img src="${attr(im)}" alt="${alts[i]||'Exercise'} position photo for ${attr(item.name)}" loading="lazy"><figcaption>${labels[i]||`${i+1} · Position`}</figcaption></figure>`;}).join('')}</div><p class="helper">Photo references to help you recognize the setup, working position and return phase. Use them as quick visual guides alongside the exercise cues below.</p>`:`<div class="notice">Illustrated demonstration pending. Follow the written steps below; stop if anything pinches or hurts.</div>`}<h3 style="margin-top:15px">Three simple cues</h3><ol class="exercise-steps">${item.steps.map(st=>`<li>${AM(st)}</li>`).join('')}</ol><a class="btn primary full" style="margin-top:12px" href="https://www.youtube.com/results?search_query=${encodeURIComponent(item.name.replace(/\s*\(each.*?\)/g,'')+' exercise proper form tutorial')}" target="_blank" rel="noopener noreferrer">▶ Find video demonstration ↗</a></section><section class="panel section"><h3>Form checkpoints</h3><p class="small" style="margin-top:9px">${AM(item.tip)}</p><div class="instruction"><b>Swap if needed:</b> ${AM(item.swap)}</div></section><button class="btn full" style="margin-top:15px" data-action="return-to-exercise">← Return to workout</button>`;
 const matches=lib.filter(x=>(x.name+' '+x.group+' '+x.equipment).toLowerCase().includes(librarySearch.toLowerCase()));
 return `<div class="eyebrow muted">REFERENCE LIBRARY</div><h1 style="margin:5px 0 9px">Exercise visuals & form</h1><p class="muted small">${lib.length} exercises from your actual 20-week plan. Tap any name for three photo reference positions, simple cues, and a demonstration search.</p><section class="section"><input class="text-field" data-input="library-search" aria-label="Search exercises" placeholder="Search exercise or muscle group" value="${attr(librarySearch)}"><div class="library-list">${matches.map(x=>`<button class="library-item" data-action="show-exercise" data-name="${attr(x.name)}"><span class="library-thumb">${x.images?.[0]?`<img src="${attr(x.images[0])}" alt="${attr(x.name)} thumbnail" loading="lazy">`:AM(x.symbol)}</span><span class="library-copy"><b>${AM(x.name)}</b><small>${AM(x.group)} · ${AM(x.equipment)}</small></span><span class="library-chevron">›</span></button>`).join('')||'<p class="empty">No matching exercises</p>'}</div></section>`;
}
function settings(){const installed=window.matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;
 return `<div class="eyebrow muted">MAKE IT YOURS</div><h1 style="margin-top:3px">Settings & backup</h1><section class="section panel"><h3>Training schedule</h3><p class="muted small" style="margin:6px 0 12px">Optional: set your first Monday, then jump to the calendar-matched week. You can always choose any week manually.</p><label class="field-label">Week 1 start date (Monday)</label><input type="date" class="text-field" data-input="setting" data-part="startDate" value="${attr(state.startDate)}"><div class="actions" style="margin-top:12px"><button class="btn light" data-action="jump-current">Jump to current calendar week</button><button class="btn" data-action="week-set" data-week="1">Start Week 1</button></div></section><section class="section panel"><h3>Backup & restore</h3><p class="muted small" style="margin:6px 0 12px">Your workouts live on THIS device, in this app's website storage. No account or cloud synchronization. Export a backup regularly and before switching phones.</p><div class="actions"><button class="btn primary" data-action="export-json">↓ Export backup</button><button class="btn" data-action="export-csv">↓ Export CSV</button><button class="btn" data-action="import-json">↑ Restore backup</button></div><input id="file-import" type="file" accept=".json,application/json" style="display:none"><p class="helper">${state.lastBackup?`Last backup exported: ${AM(state.lastBackup)}`:'No backup exported yet. Your first export is recommended now.'}</p></section><section class="section panel"><h3>Add to iPhone Home Screen</h3><p class="small" style="margin:9px 0">${installed?'<span class="status-done">✓ Running as a Home Screen app</span>':'This is an installable web app. Once it is on an HTTPS website, open its address in Safari on your iPhone, tap Share, then select Add to Home Screen.'}</p><div class="callout">After opening the hosted app once, it caches its files for offline use. Workouts you record offline are kept on the phone. Reinstalling, clearing website data, or changing devices can erase that local history unless you restore a backup.</div></section><section class="section panel"><h3>Advanced strength tracking</h3><p class="muted small" style="margin:6px 0 12px">Weight and reps are all you need for normal logging. Optional RIR (reps left in reserve) can be shown for advanced tracking; older RIR records are preserved even when hidden.</p><label class="checkitem"><input type="checkbox" data-input="setting" data-part="advancedRir" ${state.advancedRir?'checked':''}><span>Show optional RIR for strength sets</span></label></section><section class="section panel"><h3>How progression works</h3><p class="small" style="margin-top:7px">Your goal is recommended from previous logged weights and reps. A small load increase is suggested only after all planned sets reach the upper rep target at a consistent numeric weight. Missing sets, mixed loads, and modified travel sessions do not justify automatic increases. Use controlled technique and avoid grinding through pain. Recovery weeks (4, 8, 12, 16) intentionally reduce sets; Week 20 is for controlled benchmarks.</p><div class="instruction">Typical load steps: upper-body barbell +2.5–5 lb total; lower-body barbell +5–10 lb total; dumbbells smallest available increment. Don't force a weight jump when form or symptoms say otherwise.</div></section><section class="section panel"><h3>P90X & recovery</h3><p class="small" style="margin-top:7px">Use Yoga X or X Stretch on Wednesday/recovery days, and Kenpo X optionally on Saturday instead of treadmill conditioning. Keep your four prescribed strength workouts as the primary growth stimulus.</p><p class="helper">Because of your old unassessed shoulder injury and persistent neck/shoulder symptoms, book an in-person sports-medicine or physical-therapy assessment. A painless click isn't the same as sharp pinching or instability. Don't force painful motion.</p></section><section class="section panel"><h3>Privacy & data reset</h3><p class="small muted" style="margin:5px 0 12px">All entries remain on this device. This app does not send your training data to a server.</p><button class="btn" style="color:#a14b4d;border-color:#e6c4c4" data-action="reset">Delete all local workouts…</button></section><div class="footer-note">Winter Strong v5.11 · 20 weeks · 100 prescribed lifting/core sessions. Not a replacement for individualized medical assessment.</div>`;
}
function fileSave(name,text,type){const blob=new Blob([text],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function exportJSON(){state.lastBackup=new Date().toLocaleString();write();fileSave(`winter-strong-backup-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify({app:'Winter Strong',exportedAt:new Date().toISOString(),state},null,2),'application/json');toast('Backup exported');}
function csvCell(value){return `"${String(value??'').replace(/"/g,'""')}"`;}
function exportCSV(){const rows=[['Week','Day','Session type','Exercise','Variation','Set','Weight','Reps / seconds','Set RIR','Legacy exercise RIR','Legacy goal','Session completed','Session notes']];
 for(let w=1;w<=20;w++)for(const d of DAY_ORDER){const ss=getSession(w,d,false);if(!ss)continue;const travel=ss.travel?.active,entries=travel?ss.travel.entries:ss.entries;for(const en of Object.values(entries||{})){(en.sets||[]).forEach((set,j)=>{if(!V5.hasLogged(set))return;rows.push([w,FULL[d],travel?`Modified: ${ss.travel.profile} / ${ss.travel.minutes} min`:'Original',en.name,en.variant||'',j+1,set.weight||'BW',set.reps,set.rir??'',en.rir??'',en.goal||'',ss.completed?'Yes':'No',ss.notes]);});}}
 for(let w=1;w<=20;w++)for(const d of DAY_ORDER){const ss=getSession(w,d,false);for(const t of ss?.travelHistory||[]){for(const en of Object.values(t.entries||{})){(en.sets||[]).forEach((set,j)=>{if(!V5.hasLogged(set))return;rows.push([w,FULL[d],`Archived modified: ${t.profile} / ${t.minutes} min`,en.name,'',j+1,set.weight||'BW',set.reps,set.rir??'','','', 'Archived',ss.notes]);});}}}
 const csv=rows.map(r=>r.map(csvCell).join(',')).join('\r\n');fileSave(`winter-strong-v5-workouts-${new Date().toISOString().slice(0,10)}.csv`,csv,'text/csv;charset=utf-8');toast('CSV exported');}

function isValidState(s){return s&&s.version===1&&s.sessions&&typeof s.sessions==='object'&&!Array.isArray(s.sessions)&&s.checkins&&typeof s.checkins==='object'&&!Array.isArray(s.checkins);}
async function importFile(file){if(!file)return;try{if(file.size>15*1024*1024)throw Error('Backup exceeds 15 MB');const item=JSON.parse(await file.text());const incoming=item?.app==='Winter Strong'?item.state:item;if(!isValidState(incoming))throw Error('This is not a valid Winter Strong backup');if(!confirm('Replace ALL workouts on this phone with the backup? Export your current data first if needed.'))return;state={...defaultState(),...incoming};write();render();toast('Backup restored');}catch(err){alert(`Restore failed: ${err.message}`);}}
function setValueFromInput(input){const kind=input.dataset.input;if(!kind)return;const part=input.dataset.part;const val=input.type==='checkbox'?input.checked:input.value;const d=input.dataset.day||state.day,w=state.week;
 if(kind==='travel-choice'){travelPreview=travelPreview||{profile:'hotelroom',minutes:30};travelPreview[part]=part==='minutes'?Number(val):val;render();return;}
 if(kind==='set'||kind==='travel-set'){const ex=(kind==='travel-set'?getSession(w,d).travel?.exercises:PROGRAM.weeks[String(w)].days[d])?.[Number(input.dataset.ex)];if(!ex)return;const en=kind==='travel-set'?(getSession(w,d).travel.entries[Number(input.dataset.ex)]||(getSession(w,d).travel.entries[Number(input.dataset.ex)]={name:ex.name,sets:[]})):getEntry(w,d,Number(input.dataset.ex),ex.name);const j=Number(input.dataset.set);if(!en.sets[j])en.sets[j]={weight:'',reps:'',rir:''};en.sets[j][part]=val;}
 else if(kind==='exercise'){const ex=PROGRAM.weeks[String(w)].days[d]?.[Number(input.dataset.ex)];if(!ex)return;const en=getEntry(w,d,Number(input.dataset.ex),ex.name);en[part]=val;}
 else if(kind==='session'){getSession(w,d)[part]=val;if(part==='readiness'){write();render();return;}}
 else if(kind==='mobility'){getSession(w,d).mobility[input.dataset.index]=val;}
 else if(kind==='setting'){state[part]=val;if(part==='advancedRir'){write();render();return;}}
 else if(kind==='checkin'){const c=state.checkins[String(w)]||(state.checkins[String(w)]={});c[part]=val;}
 write();
}
function goCurrentWeek(){const start=new Date(`${state.startDate}T12:00:00`);if(Number.isNaN(start.getTime()))return alert('Choose a valid start date.');const monday=new Date(`${mondayNow()}T12:00:00`);const weeks=Math.floor((monday-start)/86400000/7)+1;state.week=Math.max(1,Math.min(20,weeks));state.tab='today';write();render();toast(`Showing calendar week ${state.week}`);}
function selectWeek(w){travelPreview=null;state.week=Math.max(1,Math.min(20,Number(w)||1));write();render();}
function showInfo(){if(document.querySelector('#rir-overlay'))return;const el=document.createElement('div');el.id='rir-overlay';el.className='modal-overlay';el.innerHTML=`<div class="info-modal" role="dialog" aria-modal="true" aria-labelledby="rir-heading"><div class="section-head"><h2 id="rir-heading">What is RIR?</h2><button class="btn smallbtn" data-action="rir-close" aria-label="Close explanation">✕</button></div><p><b>RIR = Reps in Reserve.</b> Estimate how many more good-form reps you could have completed <b>after each set</b>.</p><ul><li><b>0:</b> No clean reps left (failure)</li><li><b>1:</b> One more rep possible</li><li><b>2:</b> Two more reps possible</li><li><b>3:</b> Three more reps possible</li><li><b>5+:</b> Five or more possible</li></ul><p class="callout">Example: you completed 8 reps and could have done 10 with good form. Record <b>RIR 2</b> for that set.</p><p class="helper">RIR changes from set to set. Most strength sets should stop short of failure; follow the phase target and never push through pain.</p><button class="btn primary full" data-action="rir-close">Got it</button></div>`;el.addEventListener('click',e=>{if(e.target===el){el.remove();infoOpen=false;}});document.body.appendChild(el);el.querySelector('button')?.focus();}
function showEffortInfo(){if(document.querySelector('#effort-overlay'))return;const el=document.createElement('div');el.id='effort-overlay';el.className='modal-overlay';el.innerHTML=`<div class="info-modal" role="dialog" aria-modal="true" aria-labelledby="effort-heading"><div class="section-head"><h2 id="effort-heading">What is Effort Level?</h2><button class="btn smallbtn" data-action="effort-close" aria-label="Close effort explanation">✕</button></div><p>Use the <b>1–10 scale</b> to describe how difficult your conditioning workout feels.</p><ul><li><b>1–2:</b> Very easy — relaxed movement</li><li><b>3–4:</b> Easy — comfortable conversation</li><li><b>5–6:</b> Moderate — breathing harder, can speak in sentences</li><li><b>7–8:</b> Hard — can speak only in short phrases</li><li><b>9–10:</b> Very hard to maximum — difficult to sustain</li></ul><p class="callout"><b>Recommended Effort Level</b> is your workout's target. <b>Your Effort Level</b> is how hard it actually felt. Higher isn't automatically better.</p><button class="btn primary full" data-action="effort-close">Got it</button></div>`;el.addEventListener('click',e=>{if(e.target===el)el.remove();});document.body.appendChild(el);el.querySelector('button')?.focus();}
function refreshRest(){if(!restEnd)return;const left=Math.ceil((restEnd-Date.now())/1000);if(left<=0){restEnd=0;restFinished=true;updateRestWidget();beepRestComplete();toast('Rest complete');return;}const el=document.querySelector('#rest-time');if(el)el.textContent=formatTime(left);}
setInterval(refreshRest,1000);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(infoOpen){infoOpen=false;document.querySelector('#rir-overlay')?.remove();}document.querySelector('#effort-overlay')?.remove();}});
document.addEventListener('input',event=>{if(event.target.dataset.input==='library-search'){librarySearch=event.target.value;const pos=event.target.selectionStart;render();const inp=document.querySelector('[data-input=library-search]');inp?.focus();inp?.setSelectionRange(pos,pos);return;}if(event.target.matches('[data-input]')&&event.target.dataset.input!=='travel-choice')setValueFromInput(event.target);});
document.addEventListener('change',event=>{if(event.target.dataset.action==='timer-alert'){restAlert=event.target.value==='beep'?'beep':'silent';prepareRestAudio();saveRestPrefs();updateRestWidget();return;}if(event.target.dataset.action==='timer-custom'){const n=Number(event.target.value);if(Number.isInteger(n)&&n>=10&&n<=900){restDuration=n;restEnd=0;restFinished=false;saveRestPrefs();updateRestWidget();}else{toast('Choose 10–900 seconds');updateRestWidget();}return;}if(event.target.matches('[data-input]')){setValueFromInput(event.target);if(event.target.matches('input[data-part="variant"]')||event.target.dataset.input==='mobility')render();}if(event.target.id==='file-import'){importFile(event.target.files?.[0]);event.target.value='';}});
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
 if(a==='tab'){state.tab=b.dataset.tab;travelPreview=null;if(state.tab==='visuals')librarySelected=null;write();render();window.scrollTo(0,0);}
 else if(a==='show-exercise'){
   // A workout reference opens in Visuals, but remember where the user was.
   exerciseReturn=state.tab==='today'?{
     week:state.week,day:state.day,scrollY:window.scrollY,
     exerciseIndex:[...document.querySelectorAll('.exercise-card')].indexOf(b.closest('.exercise-card')),
     mobilityIndex:b.dataset.mobilityIndex!==undefined?Number(b.dataset.mobilityIndex):null
   }:null;
   librarySelected=b.dataset.name;state.tab='visuals';write();render();window.scrollTo(0,0);
 }
 else if(a==='return-to-exercise'){
   const origin=exerciseReturn;exerciseReturn=null;
   state.tab='today';travelPreview=null;
   if(origin){state.week=origin.week;state.day=origin.day;}
   librarySelected=null;write();render();
   requestAnimationFrame(()=>{
     if(origin){
       const cards=document.querySelectorAll('.exercise-card');
       const card=origin.mobilityIndex!==null?document.querySelectorAll('.mobility-row')[origin.mobilityIndex]:cards[origin.exerciseIndex];
       // Restore the exact workout location; mobility rows have their own anchors.
       window.scrollTo(0,origin.scrollY);
       if(card){const r=card.getBoundingClientRect();if(r.bottom<60||r.top>window.innerHeight-60)card.scrollIntoView({block:'center'});}
     }else window.scrollTo(0,0);
   });
 }
 else if(a==='library-back'){librarySelected=null;render();window.scrollTo(0,0);}
 else if(a==='week'){selectWeek(state.week+Number(b.dataset.step));}
 else if(a==='week-set'){selectWeek(b.dataset.week);}
 else if(a==='day'){travelPreview=null;state.day=b.dataset.day;state.tab='today';write();render();}
 else if(a==='choose-workout'){travelPreview=null;state.day=b.dataset.day;state.tab='today';write();render();window.scrollTo(0,0);}
 else if(a==='effort-info'){showEffortInfo();}
 else if(a==='effort-close'){document.querySelector('#effort-overlay')?.remove();}
 else if(a==='rir-info'){infoOpen=true;showInfo();}
 else if(a==='rir-close'){infoOpen=false;document.querySelector('#rir-overlay')?.remove();}
 else if(a==='timer-toggle'){restCollapsed=!restCollapsed;updateRestWidget();}
 else if(a==='timer-preset'){restDuration=Number(b.dataset.secs);restEnd=0;restFinished=false;saveRestPrefs();updateRestWidget();}
 else if(a==='timer-start'){prepareRestAudio();restEnd=Date.now()+1000*restDuration;restFinished=false;updateRestWidget();}
 else if(a==='timer-stop'){stopAndResetRest();}
 else if(a==='travel-edit'){const s=getSession(state.week,state.day);travelPreview={profile:s.travel?.profile||'hotelroom',minutes:s.travel?.minutes||30};render();}
 else if(a==='travel-cancel'){travelPreview=null;render();}
 else if(a==='travel-accept'){const d=state.day,ss=getSession(state.week,d),choice=travelPreview;if(!choice)return;const exs=V5.travelPlan(choice.profile,d,choice.minutes,weekData().days[d]||[]);if(!exs.length)return toast('No substitute available for this day');if(ss.travel?.active&&Object.values(ss.travel.entries||{}).some(e=>(e.sets||[]).some(V5.hasLogged))&&!confirm('Change this workout? Your previous modified sets will be preserved in the session archive.'))return;if(ss.travel?.active){ss.travelHistory ||= [];if(Object.values(ss.travel.entries||{}).some(e=>(e.sets||[]).some(V5.hasLogged)))ss.travelHistory.push({...ss.travel,archivedAt:new Date().toISOString()});}if(ss.travel&&!ss.travel.active&&ss.travel.profile===choice.profile&&ss.travel.minutes===choice.minutes){ss.travel.active=true;}else{ss.travel={...choice,active:true,exercises:exs,entries:{}};}ss.completed=false;ss.completedAt=null;travelPreview=null;write();render();toast('Modified workout ready');}
 else if(a==='travel-original'){const ss=getSession(state.week,state.day);if(ss.travel)ss.travel.active=false;ss.completed=false;ss.completedAt=null;travelPreview=null;write();render();toast('Original workout restored');}
 else if(a==='fill-goal'){const d=b.dataset.day,i=Number(b.dataset.ex),ex=weekData().days[d]?.[i];if(ex){const en=getEntry(state.week,d,i,ex.name),rx=v5Rx(state.week,d,ex,i,en).rx;for(let j=0;j<ex.sets;j++){en.sets[j] ||= {weight:'',reps:'',rir:''};if(!en.sets[j].weight&&rx.weight)en.sets[j].weight=rx.weight;}write();render();toast('Goal weight copied into empty fields');}}
 else if(a==='copy-last'){const d=b.dataset.day,i=Number(b.dataset.ex),ex=weekData().days[d]?.[i];if(ex){const en=getEntry(state.week,d,i,ex.name),prior=findPrior(state.week,d,ex.name,en.variant||'');if(prior){for(let j=0;j<ex.sets;j++){if(!en.sets[j])en.sets[j]={weight:'',reps:''};if(!en.sets[j].weight)en.sets[j].weight=prior.sets[Math.min(j,prior.sets.length-1)]?.weight||'';}write();render();toast('Previous weights filled');}}}
 else if(a==='complete'){const s=getSession(state.week,b.dataset.day);s.completed=!s.completed;s.completedAt=s.completed?new Date().toISOString():null;write();render();toast(s.completed?'Session recorded':'Session reopened');}
 else if(a==='jump-current'){goCurrentWeek();}
 else if(a==='export-json'){exportJSON();}
 else if(a==='export-csv'){exportCSV();}
 else if(a==='import-json'){document.querySelector('#file-import')?.click();}
 else if(a==='reset'){if(confirm('This permanently erases every workout and check-in stored on this device. Export a backup before continuing. Delete all data?')){state=defaultState();write();render();toast('Local data erased');}}
});
window.addEventListener('storage',event=>{if(event.key===STORE){state=load();render();}});
if('serviceWorker' in navigator && (location.protocol==='https:'||location.hostname==='localhost'))navigator.serviceWorker.register('./sw.js').catch(()=>{});
render();
})();
